  `counter` varchar(25) NOT NULL,
  `purchasecode` varchar(100) NOT NULL,
  `dealercode` varchar(25) NOT NULL,
  `category` varchar(25) NOT NULL,
  `jeweltype` varchar(25) NOT NULL,
  `subtype` varchar(50) NOT NULL,
  `pcs` int(11) NOT NULL,
  `airweight` double(12,3) NOT NULL,
  `weight` double(12,3) NOT NULL,
  `purity` double(6,3) NOT NULL,
  `waste` double(12,3) NOT NULL,
  `mc_status` varchar(10) NOT NULL,
  `mc` int(11) NOT NULL,
  `stoneweight` double(12,3) NOT NULL,
  `stoneprice` int(11) NOT NULL,
  `noofstones` int(11) NOT NULL,
  `caratsize` double(12,3) NOT NULL,
  `caratprice` int(11) NOT NULL,
  `noofcolorstones` int(11) NOT NULL,
  `colorstonesweight` double(12,3) NOT NULL,
  `colorstonesprice` int(11) NOT NULL,
  `certificatecharge` int(11) NOT NULL,
  `labourcharge` int(11) NOT NULL,
  `extracharge` int(11) NOT NULL,
  `hallmarkcharge` int(11) NOT NULL,
  `gst` double(12,3) NOT NULL,
  `gstprice` int(11) NOT NULL,
  `photoproof` varchar(255) NOT NULL,
  `billproof` varchar(255) NOT NULL,
  `pure` double(12,3) NOT NULL,
  `total_pure` double(12,3) NOT NULL,
  `cash` int(11) NOT NULL,
  `total_cash` double(12,3) NOT NULL,
  `buy` varchar(20) NOT NULL,
  `rate` int(11) NOT NULL,
  `payment` varchar(20) NOT NULL,
  `bank` int(11) NOT NULL,
  `bankname` varchar(25) NOT NULL,
  `transactiontype` varchar(25) NOT NULL,
  `uniqueid` int(11) NOT NULL AUTO_INCREMENT,
  `branch` varchar(50) NOT NULL,
  `system_info` varchar(128) NOT NULL,
  `deleteon` date NOT NULL,
  `deleteat` time NOT NULL,
  `deleteid` varchar(100) NOT NULL,
  `deletename` varchar(50) NOT NULL,
  `entrydate` date NOT NULL,
  `entrytime` time NOT NULL,
  `enteredbyid` varchar(100) NOT NULL,
  `enteredbyname` varchar(50) NOT NULL,
  PRIMARY KEY (`uniqueid`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
