DROP TABLE IF EXISTS `jewel_master_control`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `jewel_master_control` (
  `category` varchar(20) NOT NULL,
  `jeweltype` varchar(50) NOT NULL,
  `code` varchar(5) NOT NULL,
  `measure` varchar(10) NOT NULL,
  `saletype` varchar(10) NOT NULL,
  `samplepic` varchar(255) NOT NULL,
  `subtype` varchar(100) NOT NULL,
  `minweight` double(8,3) NOT NULL,
  `maxweight` double(8,3) NOT NULL,
  `spltype` varchar(10) NOT NULL,
  `splprice` int(11) NOT NULL,
  `wastetype` varchar(10) NOT NULL,
  `minwaste` double(8,3) NOT NULL,
  `maxwaste` double(8,3) NOT NULL,
  `mctype` varchar(10) NOT NULL,
  `minmc` double(8,3) NOT NULL,
  `maxmc` double(8,3) NOT NULL,
  `commissiontype` varchar(10) NOT NULL,
  `commissionvalue` int(11) NOT NULL,
  `uniqueid` int(11) NOT NULL AUTO_INCREMENT,
  `branch` varchar(50) NOT NULL,
  `system_info` varchar(128) NOT NULL,
  `deleteon` date NOT NULL,
  `deleteat` time NOT NULL,
  `deleteid` varchar(100) NOT NULL,
  `deletename` varchar(50) NOT NULL,
  `entrydate` date NOT NULL,
  `entrytime` time NOT NULL,
  `enteredbyid` varchar(100) NOT NULL,
  `enteredbyname` varchar(50) NOT NULL,
  PRIMARY KEY (`uniqueid`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
