--
-- Table structure for table `ledger`
--

DROP TABLE IF EXISTS `ledger`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ledger` (
  `type` varchar(25) NOT NULL,
  `fromm` varchar(25) NOT NULL,
  `id` varchar(100) NOT NULL,
  `transaction_id` int(11) NOT NULL,
  `account_id` int(11) NOT NULL,
  `bookkeeping` varchar(100) NOT NULL,
  `debit` double(15,3) NOT NULL,
  `credit` double(15,3) NOT NULL,
  `entity_id` varchar(50) NOT NULL,
  `date` date NOT NULL,
  `suspense` int(11) NOT NULL,
  `uniqueid` int(11) NOT NULL AUTO_INCREMENT,
  `branch` varchar(50) NOT NULL,
  `system_info` varchar(128) NOT NULL,
  `deleteon` date NOT NULL,
  `deleteat` time NOT NULL,
  `deleteid` varchar(100) DEFAULT NULL,
  `deletename` varchar(50) NOT NULL,
  `entrydate` date NOT NULL,
  `entrytime` time NOT NULL,
  `enteredbyid` varchar(100) DEFAULT NULL,
  `enteredbyname` varchar(50) NOT NULL,
  PRIMARY KEY (`uniqueid`),
  KEY `fk` (`account_id`)
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

