CREATE TABLE `tagged_jewels` (
  `counter` varchar(25) NOT NULL,
  `category` varchar(25) NOT NULL,
  `tagid` varchar(25) NOT NULL,
  `lotno` varchar(20) NOT NULL,
  `code` varchar(10) NOT NULL,
  `jeweltype` varchar(50) NOT NULL,
  `subtype` varchar(50) NOT NULL,
  `pcs` int(11) NOT NULL,
  `purity` double(6,3) NOT NULL,
  `weight` double(12,3) NOT NULL,
  `totalstoneweight` double(12,3) NOT NULL,
  `totaladdonweight` double(12,3) NOT NULL,
  `stonetype` longtext NOT NULL,
  `stonecount` longtext NOT NULL,
  `stoneweight` longtext NOT NULL,
  `stoneprice` longtext NOT NULL,
  `caratsize` longtext NOT NULL,
